CREATE TABLE IF NOT EXISTS mcp_profiles (id VARCHAR(36) PRIMARY KEY, slug VARCHAR(191) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, description TEXT NOT NULL, permissions TEXT NOT NULL, tools TEXT NOT NULL, built_in BOOLEAN NOT NULL, enabled BOOLEAN NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS mcp_connections (id VARCHAR(36) PRIMARY KEY, slug VARCHAR(191) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, workspace_id VARCHAR(36) NULL, project_id VARCHAR(36) NULL, profile_id VARCHAR(36) NOT NULL, auth_type VARCHAR(32) NOT NULL, credential_hash VARCHAR(191) NOT NULL UNIQUE, enabled BOOLEAN NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, last_used_at VARCHAR(40) NULL, KEY idx_mcp_connections_scope(workspace_id,project_id,enabled), FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(profile_id) REFERENCES mcp_profiles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skill_proposals (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL, base_version INT NOT NULL, proposed_snapshot LONGTEXT NOT NULL, summary TEXT NOT NULL, status VARCHAR(32) NOT NULL, created_by VARCHAR(191) NULL, reviewed_by VARCHAR(191) NULL, review_note TEXT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, reviewed_at VARCHAR(40) NULL, KEY idx_skill_proposals_status(status,skill_id,created_at), FOREIGN KEY(skill_id) REFERENCES skills(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS execution_events (id VARCHAR(36) PRIMARY KEY, execution_id VARCHAR(36) NOT NULL, position INT NOT NULL, event_type VARCHAR(191) NOT NULL, event_data LONGTEXT NOT NULL, created_at VARCHAR(40) NOT NULL, UNIQUE KEY uq_execution_event_position(execution_id,position), FOREIGN KEY(execution_id) REFERENCES skill_executions(id) ON DELETE CASCADE) ENGINE=InnoDB;
